//! Terminal output must not dispatch arbitrary paths to ShellExecuteW.
//! Keep this policy independent of Win32 so it can be tested without UI.
const std = @import("std");
const OpenUrl = @import("../action.zig").OpenUrl;

pub const Decision = enum { allow, confirm, deny };

pub fn decide(value: OpenUrl) Decision {
    switch (value.kind) {
        // These paths are generated by Ghostty, not the terminal program.
        .text, .html => return .allow,
        .unknown, .osc8 => {},
    }
    if (value.url.len == 0) return .deny;
    const view = std.unicode.Utf8View.init(value.url) catch return .deny;
    var iter = view.iterator();
    while (iter.nextCodepoint()) |cp| switch (cp) {
        0...0x20,
        0x7F...0x9F,
        '\\',
        0x061C,
        0x200B...0x200F,
        0x2028...0x202E,
        0x2060,
        0x2066...0x2069,
        0xFEFF,
        => return .deny,
        else => {},
    };
    const uri = std.Uri.parse(value.url) catch return .deny;
    // A drive path can parse as a URI with a one-letter scheme. Never
    // reinterpret it as a custom protocol and pass it to ShellExecute.
    if (uri.scheme.len <= 1) return .deny;
    if (std.ascii.eqlIgnoreCase(uri.scheme, "http") or
        std.ascii.eqlIgnoreCase(uri.scheme, "https"))
    {
        const host = uri.host orelse return .deny;
        return if (host.isEmpty()) .deny else .allow;
    }
    if (std.ascii.eqlIgnoreCase(uri.scheme, "mailto")) {
        return if (uri.path.isEmpty()) .deny else .allow;
    }
    // Unlike macOS, Windows has no non-executable-file bit. File associations,
    // shortcuts, reparse points and extensionless executables make a simple
    // extension blacklist unsafe. Until canonical safe-file classification
    // exists, refuse all terminal-supplied local/remote file targets.
    if (std.ascii.eqlIgnoreCase(uri.scheme, "file")) return .deny;
    return .confirm;
}

test "terminal URL policy blocks paths and unsafe or malformed targets" {
    for ([_][]const u8{
        "",                          "notes.txt",                "../run.cmd",                     "C:/Windows/notepad.exe",          "C:\\run.exe",
        "\\\\server\\run.exe",       "file:///C:/run.exe",       "FILE://server/share/readme.txt", "https:relative",                  "https://",
        "https://example.com/\nrun", "https://example.com/\x00", "https://example.com/\xff",       "https://example.com/\u{202E}exe", "https://example.com/a b",
        "mailto:",                   "https:\\example.com",
    }) |url| {
        for ([_]OpenUrl.Kind{ .unknown, .osc8 }) |kind| {
            try std.testing.expectEqual(Decision.deny, decide(.{ .kind = kind, .url = url }));
        }
    }
}

test "terminal URL policy allows web and mail and confirms custom protocols" {
    for ([_][]const u8{ "https://example.com/path", "HTTP://localhost:8080/", "https://[::1]/", "mailto:user@example.com" }) |url| {
        try std.testing.expectEqual(Decision.allow, decide(.{ .kind = .osc8, .url = url }));
    }
    try std.testing.expectEqual(Decision.confirm, decide(.{ .kind = .osc8, .url = "vscode://file/C:/src/main.zig" }));
    try std.testing.expectEqual(Decision.allow, decide(.{ .kind = .text, .url = "C:\\temp\\screen.txt" }));
    try std.testing.expectEqual(Decision.allow, decide(.{ .kind = .html, .url = "C:\\temp\\screen.html" }));
}
